function proj(x,y,z=0){return {x:(x-y)*TW*.5+camX,y:(x+y)*TH*.5+camY-z}}
function unproj(x,y){let px=(x-camX)/(TW*.5),py=(y-camY)/(TH*.5);return {x:(px+py)/2,y:(py-px)/2}}
