function drawTree(o,p){let s=.85+o.seed*.38;drawShadow(p,s);ctx.strokeStyle='#875d40';ctx.lineWidth=11*s;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x,p.y-37*s);ctx.stroke();ellipse(p.x-13*s,p.y-43*s,21*s,19*s,'#4d9f61');ellipse(p.x+16*s,p.y-46*s,23*s,23*s,'#59b66c');ellipse(p.x,p.y-63*s,28*s,26*s,'#70bf71');ellipse(p.x-11*s,p.y-65*s,8*s,4*s,'#91d88a')}
