if(act==='pickItem'){uiSelectedFurniture=id;renderInterior();return}
if(act==='wallColor'||act==='floorColor'){setRoomColor(act==='wallColor'?'wall':'floor',target.dataset.color);return}
if(act==='craft'){craftFurniture(id);return}
