// Resident schedules — each individual Fathermon visits meaningful places during the day.
const oldGameUpdate=gameUpdate;
gameUpdate=function(dt){if(state&&!paused&&!activeModal){for(const n of npcData){if(!state.residents.includes(n.index))continue;let h=state.clock,goal,activity;
if(h>=21||h<7){goal={x:n.home.x+1.2,y:n.home.y+1};activity='Resting at home'}
else if(h<11){goal={x:20+(n.index%3)*.65,y:19+((n.index*3)%3)*.7};activity='Visiting the town square'}
else if(h<16){goal=n.index%3===0?{x:28.5,y:28}:n.index%3===1?{x:12,y:27}:{x:23,y:22};activity=n.index%3===0?'Helping at the workshop':n.index%3===1?'Exploring the pond':'Tending the town gardens'}
else{goal={x:20+(n.index%3),y:20+(n.index%2)};activity='Meeting neighbors'}
n.activity=activity;if(n.lastActivity!==activity){n.lastActivity=activity;n.target={x:goal.x+hash(n.index,3),y:goal.y+hash(n.index,9)};n.wander=5}
}}
oldGameUpdate(dt);if(miniFishing&&$('catchBobber')&&!$('modal').classList.contains('hidden')){let p=(Math.sin((performance.now()-miniFishing.begin)/320)+1)/2;$('catchBobber').style.left=(p*100)+'%'}
};
// Map world objects, backed by original v0.3 isometric drawing engine.
function drawPond(p){ellipse(p.x,p.y,118,57,'#5f9d85');ellipse(p.x,p.y-5,108,52,'#59bfc4');ellipse(p.x-15,p.y-11,86,37,'#81ded9');for(let i=0;i<5;i++){ellipse(p.x-65+i*32,p.y-13+(i%2)*14,6,3,'#d8fff4')}ctx.font='bold 12px Trebuchet MS';ctx.textAlign='center';ctx.fillStyle='#e9fff8';ctx.fillText('🎣 LITTLE POND',p.x,p.y-23)}
function drawOldWorkshop(p){drawShadow(p,2);const fixed=state.workshopRestored;drawPoly([[p.x-61,p.y-38],[p.x,p.y-70],[p.x+61,p.y-38],[p.x,p.y-8]],fixed?'#ffd89a':'#c4ad95','#80593c',2);drawPoly([[p.x-61,p.y-38],[p.x,p.y-8],[p.x,p.y+21],[p.x-61,p.y-10]],fixed?'#c69b77':'#988985','#775d56',2);drawPoly([[p.x,p.y-8],[p.x+61,p.y-38],[p.x+61,p.y-10],[p.x,p.y+21]],fixed?'#9ad1ad':'#aaa39c','#775d56',2);ctx.fillStyle=fixed?'#6b5135':'#7a6c5b';ctx.fillRect(p.x-35,p.y-46,69,20);ctx.fillStyle='#fff2ce';ctx.textAlign='center';ctx.font='bold 12px Trebuchet MS';ctx.fillText(fixed?'🔧 WORKSHOP':'🔧 REPAIR ME',p.x,p.y-31);ctx.fillStyle='#795a42';ctx.fillRect(p.x+20,p.y-8,20,19);if(fixed){ellipse(p.x-49,p.y-16,7,6,'#f9db77');ellipse(p.x+55,p.y-20,7,6,'#f9db77')}}
function drawMarket(p){drawShadow(p,1.8);ctx.fillStyle='#91623e';ctx.fillRect(p.x-35,p.y-9,70,24);ctx.fillStyle='#eac797';ctx.fillRect(p.x-38,p.y-35,76,17);for(let i=0;i<6;i++){ctx.fillStyle=i%2?'#fff4d1':'#ee9797';ctx.fillRect(p.x-40+i*13,p.y-53,13,21)}ctx.fillStyle='#fff2cc';ctx.fillRect(p.x-38,p.y-63,76,12);ctx.textAlign='center';ctx.fillStyle='#594234';ctx.font='bold 10px Trebuchet MS';ctx.fillText('TOWN MARKET',p.x,p.y-54);ellipse(p.x-15,p.y-15,8,6,'#f5cb72');ellipse(p.x+11,p.y-12,9,7,'#d88c76')}
function drawGarden(p,b){drawShadow(p,1.5);drawPoly([[p.x,p.y-29],[p.x+38,p.y-10],[p.x,p.y+10],[p.x-38,p.y-10]],'#8b5639','#c79661',2);for(let i=0;i<3;i++){let xp=p.x+(i-1)*18;ctx.strokeStyle='#5b924e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(xp,p.y-13);ctx.lineTo(xp,p.y-30-Math.min(b.growth||0,2)*4);ctx.stroke();ellipse(xp-5,p.y-29-Math.min(b.growth||0,2)*4,7,5,b.growth>=2?'#eb9d4c':'#8cbe63')}if(b.watered){ctx.textAlign='center';ctx.font='14px sans-serif';ctx.fillText('💧',p.x+14,p.y-34)}}
const oldDrawBuild=drawBuild;
drawBuild=function(o,p){if(o.type==='market'){drawMarket(p);return}if(o.type==='garden'){drawGarden(p,o);return}oldDrawBuild(o,p)};
