// Pinch zoom: keep drawing in the original projection and scale around the player's view.
const oldRender=render;
render=function(){if(!state)return;ctx.save();ctx.translate(cw*.5,ch*.55);ctx.scale(currentZoom,currentZoom);ctx.translate(-cw*.5,-ch*.55);oldRender();ctx.restore()};
const world=$('world');
world.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&touchStartDistance!==null)return;if(currentZoom===1)return;if(paused||activeModal)return;e.preventDefault();e.stopImmediatePropagation();let r=world.getBoundingClientRect(), sx=(e.clientX-r.left-cw*.5)/currentZoom+cw*.5, sy=(e.clientY-r.top-ch*.55)/currentZoom+ch*.55;let p=unproj(sx,sy);if(placing){buildAt(p.x,p.y);return}if(!inside(p.x,p.y))return;let nearest=null,best=1.6;for(let i of state.residents){let d=dist(npcData[i],p);if(d<best){best=d;nearest=i}}if(nearest!==null){if(dist(state.player,npcData[nearest])<3.3)talkTo(nearest);else{walkTarget={x:npcData[nearest].x+.8,y:npcData[nearest].y+.5};pendingTalk=nearest}return}walkTarget=p;pendingTalk=null},true);
const pointers=new Map();
world.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'){pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const a=[...pointers.values()];touchStartDistance={distance:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y),zoom:currentZoom};walkTarget=null}}});
world.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2&&touchStartDistance){const a=[...pointers.values()];const d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);setZoom(touchStartDistance.zoom*d/Math.max(1,touchStartDistance.distance))}});
const finishTouch=e=>{pointers.delete(e.pointerId);if(pointers.size<2)touchStartDistance=null};world.addEventListener('pointerup',finishTouch);world.addEventListener('pointercancel',finishTouch);
// Replace the virtual control calibration with responsive sizing.
setJoy=function(clientX,clientY){let r=joystick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=clientX-cx,dy=clientY-cy,max=r.width*.3,len=Math.hypot(dx,dy),ratio=Math.min(1,max/Math.max(.01,len));let x=dx*ratio,y=dy*ratio;knob.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`;let dead=r.width*.065;joyX=len<dead?0:x/max;joyY=len<dead?0:y/max;knob.classList.toggle('active',!!(joyX||joyY))};
// Touch-tap on a landmark routes the player there. When close enough, interact.
world.addEventListener('click',e=>{if(paused||activeModal||placing||touchStartDistance!==null)return;const r=world.getBoundingClientRect(),sx=(e.clientX-r.left-cw*.5)/currentZoom+cw*.5,sy=(e.clientY-r.top-ch*.55)/currentZoom+ch*.55,p=unproj(sx,sy);if(dist(p,{x:28.5,y:28})<2){if(dist(state.player,{x:28.5,y:28})<3.4)inspectWorkshop();else goTo(28.5,28,'the workshop')}else if(dist(p,{x:10,y:28})<2){if(dist(state.player,{x:10,y:28})<3.1)showFishing();else goTo(10,28,'the pond')}},true);
