// FATHERMON TOWNSHIP v0.5 — Build Your Dream Town.
// Native offline WebGL world, original art as textured billboards; legacy v0.4 systems retained.
const V05_KEY='fathermon_township_v05_dream_town_save';
const originalV05Make=makeState;
makeState=function(){return {...originalV05Make(),version:5,terrainEdits:[],expansions:[],chapter3Started:false,chapter3Step:0,chapter3Complete:false,editorVisited:false,styledHomes:0,movedBuildings:0,cameraAngle:0.8,cameraElevation:0.79,lowGraphics:false,undoHistory:[]}};
function normalizeV05(v){let b=normalizeV04(v),d=makeState();return {...d,...b,version:5,terrainEdits:Array.isArray(v.terrainEdits)?v.terrainEdits:[],expansions:Array.isArray(v.expansions)?v.expansions:[],undoHistory:Array.isArray(v.undoHistory)?v.undoHistory.slice(-12):[],cameraAngle:Number.isFinite(v.cameraAngle)?v.cameraAngle:0.8,cameraElevation:Number.isFinite(v.cameraElevation)?v.cameraElevation:.79,chapter3Step:v.chapter3Step||0,styledHomes:v.styledHomes||0,movedBuildings:v.movedBuildings||0};}
loadSave=function(){try{let v=JSON.parse(localStorage.getItem(V05_KEY)||'null');if(v&&v.version===5)return normalizeV05(v);let old=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(old&&old.version===4)return normalizeV05(old);let v3=JSON.parse(localStorage.getItem('fathermon_township_v03_first_resident_save')||'null');if(v3&&v3.version===3)return normalizeV05(v3);}catch(e){console.warn('Save read',e)}return null};
