const v05OldStart=startGame;
startGame=function(saved=false){v05OldStart(saved);state=normalizeV05(state);setupNpcs();document.title='Fathermon Township · Build Your Dream Town v0.5';$('chapterTag').textContent=state.chapter2Complete?'CHAPTER 3 · THE FIRST NEIGHBORHOOD':$('chapterTag').textContent;document.documentElement.style.setProperty('--joystick-size',(state.controlSize||156)+'px');persist();updateHUD();};
const v05OldShowIntro=showIntro;
showIntro=function(){v05OldShowIntro();let s=$('intro').querySelector('.subtitle');if(s)s.textContent='Arrive alone · Build in 3D · Welcome Fathermon neighbors';const logo=$('intro').querySelector('.logo');if(logo)logo.insertAdjacentHTML('beforeend','<small style="display:block;font-size:14px;letter-spacing:1px;color:#c18544;margin:8px">BUILD YOUR DREAM TOWN · v0.5</small>');};
const v05OldUpdateHUD=updateHUD;
updateHUD=function(){if(!state)return;v05OldUpdateHUD();if(state.chapter2Complete){$('chapterTag').textContent='🏘️ CHAPTER 3 · THE FIRST NEIGHBORHOOD';const q=chapterThreeTasks()[Math.min(state.chapter3Step,6)];$('questTitle').textContent=q[0];$('questText').textContent=q[1];$('questProgress').style.width=(state.chapter3Step/6*100)+'%';}};
const chapterThreeTasks=()=>[
['A neighborhood needs a plan','Open ✨ Town → 🎨 Design Studio and look at the new construction tools.'],
['Connect your neighbors','Use the Path tool to place a new footpath.'],
['Make the land your own','Add a Pond or Hill using the terrain editor.'],
['A house with personality','Tap a cottage in House Styles and customize its roof, walls or windows.'],
['Make some room','Use Move mode to drag a placed decoration or building.'],
['Room to grow','Invite neighbors, then unlock a new district plot from the Design Studio.'],
['The First Neighborhood complete!','Your little township now has a real neighborhood. Keep creating your dream town!']];
function scene3(text,title,icon,button='Keep building'){showModal(`<div class="eyebrow">🏘️ CHAPTER 3 · THE FIRST NEIGHBORHOOD</div><div class="storyHero"><div class="storyIcon">${icon}</div><div><h2>${title}</h2><p>${text}</p></div></div><div class="storyPartner"><img src="${FILES[state.avatar]}" alt="${NAMES[state.avatar]}"><span><b>${NAMES[state.avatar]}</b><small>You gave an empty place a future.</small></span></div><div class="actions"><button class="btn" data-v05="close">${button}</button><button class="btn secondary" data-v05="studio">🎨 Design Studio</button></div>`)}
function startChapter3(){if(!state.chapter2Complete||state.chapter3Started)return;state.chapter3Started=true;state.chapter3Step=0;persist();scene3(`The workshop is humming, neighbors are settling in, and ${esc(state.townName)} is growing. A faded neighborhood blueprint turns up beneath the town noticeboard. It shows gardens, pathways, and room for new cottages. It is time to turn your settlement into a place everyone can call home.`,'A blueprint for belonging','🗺️','Begin Chapter 3');}
function checkChapter3(){if(!state||!state.chapter2Complete||state.chapter3Complete)return;let s=state.chapter3Step,pass=[state.editorVisited,state.terrainEdits.some(t=>t.type==='path'),state.terrainEdits.some(t=>t.type==='pond'||t.type==='hill'),state.styledHomes>0,state.movedBuildings>0,state.expansions.length>0][s];if(pass){state.chapter3Step++;state.coins+=20;if(state.chapter3Step>=6){state.chapter3Complete=true;state.coins+=80;persist();scene3(`From your first lonely night in the meadow to a neighborhood filled with Fathermon, you built something beautiful. The new district is open, and your town has a bright future.`,'A real township at last!','🎉','Celebrate!')}else{persist();toast(`🏘️ Chapter 3 progress! +20 coins · ${chapterThreeTasks()[state.chapter3Step][0]}`,4300)}updateHUD()}}
