function snapshot(){state.undoHistory.push(JSON.stringify({built:state.built,terrainEdits:state.terrainEdits,expansions:state.expansions,wood:state.wood,stone:state.stone,petals:state.petals,coins:state.coins,styledHomes:state.styledHomes,movedBuildings:state.movedBuildings}));if(state.undoHistory.length>12)state.undoHistory.shift()}
function undoDesign(){let data=state.undoHistory.pop();if(!data){toast('Nothing to undo yet');return}let s=JSON.parse(data);Object.assign(state,s);setupNpcs();persist();updateHUD();toast('↶ Last design change undone')}
const v05OldBuildAt=buildAt;
