const expansionDefs=[{id:'north',name:'Willow Hills',required:1,cost:35,x0:6,x1:36,z0:2,z1:9},{id:'east',name:'Sunrise Meadow',required:2,cost:55,x0:34,x1:40,z0:7,z1:35},{id:'west',name:'Mossy Grove',required:3,cost:75,x0:2,x1:9,z0:7,z1:35},{id:'south',name:'Bluebell Banks',required:4,cost:100,x0:7,x1:35,z0:32,z1:36}];
