function activateDesigner(mode,type){if(!state)return;designer.mode=mode;designer.type=type||null;designer.drag=null;designer.ghost=null;if(placing)endPlacing();hideModal();$('designerDock').classList.remove('hidden');$('designTool').textContent=mode==='place'?`🏗️ Place ${COST[type]?.name||type}`:mode==='terrain'?`🪴 Paint ${type}`:mode==='move'?'✋ Drag or tap a structure to move':mode==='style'?'🎨 Tap a cottage to customize':'🗑️ Tap a structure to remove';toast('🎨 '+$('designTool').textContent);}
