function canSite(x,z,exclude=null,type='path'){if(!plotOpen(x,z)||!inside(x,z))return false;if(type==='cottage'&&dist({x,z},{x:28.5,y:28})<3)return false;if(state.built.some(b=>b!==exclude&&Math.hypot(x-b.x,z-b.y)<(type==='cottage'||b.type==='cottage'?2.9:1.25)))return false;return true}
function terrainAt(x,z,type){x=Math.round(x);z=Math.round(z);if(!plotOpen(x,z)){toast('Unlock this district to work here');return}if(!inside(x,z)||!canSite(x,z,null,type)){toast('Choose an open plot for that');return}let cfg=terrainDefs.find(t=>t[0]===type),cost={wood:cfg[3],stone:cfg[4],petals:cfg[5]};for(const k in cost)if(state[k]<cost[k]){toast('Gather more materials to make a '+type);return}snapshot();for(const k in cost)state[k]-=cost[k];state.terrainEdits=state.terrainEdits.filter(t=>!(t.x===x&&t.y===z));state.terrainEdits.push({x,y:z,type});sound(640);toast('🪴 '+type+' placed · tap again to paint another');persist();checkChapter3();updateHUD()}
function removeAt(x,z){const idx=state.built.findIndex(b=>dist({x,y:z},b)<(b.type==='cottage'?2.4:1.35));if(idx>=0){const b=state.built[idx];if(b.type==='cottage'&&b.resident!==null){toast('Neighbors live here! Move their home instead of removing it.');return}snapshot();state.built.splice(idx,1);const c=COST[b.type];if(c){state.wood+=Math.floor(c.wood/2);state.stone+=Math.floor(c.stone/2);state.petals+=Math.floor(c.petals/2)}setupNpcs();toast('🗑️ Structure removed; some materials returned');persist();return}const i=state.terrainEdits.findIndex(t=>Math.hypot(t.x-x,t.y-z)<1.1);if(i>=0){snapshot();state.terrainEdits.splice(i,1);persist();toast('🗑️ Terrain decoration removed')}else toast('Tap a placed structure or edited terrain to remove')}
function pickStructure(x,z){let nearest=null,best=3.1;for(const b of state.built){let d=Math.hypot(x-b.x,z-b.y);if(d<best){best=d;nearest=b}}return nearest}
