function updateCamera(){let x=state?.player.x||20,z=state?.player.y||19;let distv=clamp(27/currentZoom,13,48);let yaw=scene3d.yaw,pitch=scene3d.pitch;scene3d.dist=distv;scene3d.target=[x,0,z];let c=Math.cos(yaw),s=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);scene3d.eye=[x+c*cp*distv,sp*distv,z+s*cp*distv];scene3d.forward=[-c*cp,-sp,-s*cp];scene3d.right=[s,0,-c];scene3d.up=[-c*sp,cp,-s*sp];scene3d.aspect=world3d.width/world3d.height;}
function syncGLSize(){if(!glReady)return;let pixelRatio=Math.min(state?.lowGraphics?1:1.6,window.devicePixelRatio||1),w=Math.round(world3d.clientWidth*pixelRatio),h=Math.round(world3d.clientHeight*pixelRatio);if(w!==world3d.width||h!==world3d.height){world3d.width=w;world3d.height=h;gl.viewport(0,0,w,h)}}
function glBind(buffer,prog,arr){gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(arr),gl.DYNAMIC_DRAW);const stride=8*4;for(const [name,size,offset] of [['aPos',3,0],['aCol',3,12],['aUV',2,24]]){const loc=gl.getAttribLocation(prog,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,stride,offset)}}
function setCameraUniforms(prog){let p=scene3d;gl.uniform3fv(gl.getUniformLocation(prog,'uEye'),p.eye);gl.uniform3fv(gl.getUniformLocation(prog,'uRight'),p.right);gl.uniform3fv(gl.getUniformLocation(prog,'uUp'),p.up);gl.uniform3fv(gl.getUniformLocation(prog,'uForward'),p.forward);gl.uniform1f(gl.getUniformLocation(prog,'uAspect'),p.aspect);gl.uniform1f(gl.getUniformLocation(prog,'uTan'),p.tan)}
function spriteQuad(pos,id){const ref=textureArray[id];if(!ref)return null;let x=pos.x,z=pos.y,scale=pos.player?2.35:1.98;let width=scale*Math.min(1.35,ref.aspect);let right=scene3d.right,bob=Math.sin(tick*2+(pos.index||0))*.05;let y0=.17+bob,y1=y0+scale;let a=[x-right[0]*width/2,y0,z-right[2]*width/2],b=[x+right[0]*width/2,y0,z+right[2]*width/2],c=[x+right[0]*width/2,y1,z+right[2]*width/2],d=[x-right[0]*width/2,y1,z-right[2]*width/2];let t=[],vert=(p,uv)=>t.push(...p,1,1,1,...uv);vert(a,[0,1]);vert(b,[1,1]);vert(c,[1,0]);vert(a,[0,1]);vert(c,[1,0]);vert(d,[0,0]);return t}
