render=function(){if(!state)return;if(!glReady){legacyRenderedV05();return}syncGLSize();updateCamera();gl.clearColor(state.clock>=19?.22:.62,state.clock>=19?.32:.83,state.clock>=19?.42:.85,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(meshProgram);setCameraUniforms(meshProgram);gl.uniform1i(gl.getUniformLocation(meshProgram,'uSprite'),0);let g=new Geometry();addTerrain3d(g);glBind(meshVBO,meshProgram,g.a);gl.drawArrays(gl.TRIANGLES,0,g.a.length/8);
let chars=[{x:state.player.x,y:state.player.y,index:state.avatar,player:true},...npcData.filter(n=>state.residents.includes(n.index)).map(n=>({x:n.x,y:n.y,index:n.index}))];chars.sort((a,b)=>{let e=scene3d.eye;return Math.hypot(b.x-e[0],b.y-e[2])-Math.hypot(a.x-e[0],a.y-e[2])});gl.uniform1i(gl.getUniformLocation(meshProgram,'uSprite'),1);gl.depthMask(false);for(const ch of chars){let q=spriteQuad(ch,ch.index);let img=textureArray[ch.index];if(!q||!img)continue;glBind(spriteVBO,meshProgram,q);gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,img.tex);gl.uniform1i(gl.getUniformLocation(meshProgram,'uTex'),0);gl.drawArrays(gl.TRIANGLES,0,6)}gl.depthMask(true);frameRendered++;};
function rayToGround(clientX,clientY){let r=world3d.getBoundingClientRect();let nx=2*(clientX-r.left)/r.width-1,ny=1-2*(clientY-r.top)/r.height,c=scene3d,p=c.forward,right=c.right,up=c.up;let dx=p[0]+right[0]*nx*c.aspect*c.tan+up[0]*ny*c.tan,dy=p[1]+up[1]*ny*c.tan,dz=p[2]+right[2]*nx*c.aspect*c.tan+up[2]*ny*c.tan;if(dy>=-.025)return null;let t=-c.eye[1]/dy;return{x:c.eye[0]+dx*t,y:c.eye[2]+dz*t}}
