const oldV05GameUpdate=gameUpdate;
gameUpdate=function(dt){let jx=joyX,jy=joyY,k=[...keys];let rx=scene3d.right[0],rz=scene3d.right[2],fx=-Math.cos(scene3d.yaw),fz=-Math.sin(scene3d.yaw);let ix=jx+(keys.has('right')?1:0)-(keys.has('left')?1:0),iy=jy+(keys.has('down')?1:0)-(keys.has('up')?1:0);if(ix||iy){let wx=ix*rx-iy*fx,wz=ix*rz-iy*fz;joyX=(wx-wz)/2;joyY=(wx+wz)/2;keys.delete('up');keys.delete('down');keys.delete('left');keys.delete('right')}
oldV05GameUpdate(dt);joyX=jx;joyY=jy;for(let key of k)keys.add(key)};
let touchPointers=new Map(),cameraDrag=null,tapCandidate=null,justPinched=false;
function modeTap(pos){if(!pos||!inside(pos.x,pos.y))return;if(designer.mode==='terrain'){terrainAt(pos.x,pos.y,designer.type);return}if(designer.mode==='place'){if(!canSite(pos.x,pos.y,null,designer.type)){toast('Choose an open plot in your unlocked area');return}placing=designer.type;let before=state.built.length;buildAt(pos.x,pos.y);if(state.built.length!==before)designer.mode='off',designerDock.classList.add('hidden');return}if(designer.mode==='style'){let b=pickStructure(pos.x,pos.y),i=state.built.indexOf(b);if(b&&b.type==='cottage')showHouseStyle(i);else toast('Tap a built cottage to customize it');return}if(designer.mode==='remove'){removeAt(pos.x,pos.y);return}if(designer.mode==='move'){let b=pickStructure(pos.x,pos.y);if(!b){toast('Tap or drag a building or decoration');return}designer.chosen=b;designer.ghost={x:b.x,z:b.y};toast('Drag to the new position, or tap an open spot');return}
let hit=pickStructure(pos.x,pos.y);if(hit&&hit.type==='cottage'&&Math.hypot(hit.x-pos.x,hit.y-pos.y)<1.4){showHouseStyle(state.built.indexOf(hit));return}
let near=state.residents.find(i=>Math.hypot(npcData[i].x-pos.x,npcData[i].y-pos.y)<1.2);if(near!==undefined){let n=npcData[near];if(dist(state.player,n)<3.3)talkTo(near);else{walkTarget={x:n.x+.8,y:n.y+.4};pendingTalk=near}return}if(dist(pos,{x:28.5,y:28})<2.4){if(dist(state.player,{x:28.5,y:28})<3.4)inspectWorkshop();else goTo(28.5,28,'the workshop');return}if(dist(pos,{x:10,y:28})<2){if(dist(state.player,{x:10,y:28})<3.2)showFishing();else goTo(10,28,'the pond');return}walkTarget=pos;pendingTalk=null;}
world3d.addEventListener('pointerdown',e=>{if(paused||activeModal)return;e.preventDefault();world3d.setPointerCapture?.(e.pointerId);touchPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(e.button===2||e.shiftKey){cameraDrag={x:e.clientX,y:e.clientY,yaw:scene3d.yaw,pitch:scene3d.pitch};return}if(touchPointers.size===2){let p=[...touchPointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);cameraDrag={pinch:true,distance:d,yaw:scene3d.yaw,pitch:scene3d.pitch,zoom:currentZoom,cx:(p[0].x+p[1].x)/2,cy:(p[0].y+p[1].y)/2};tapCandidate=null;justPinched=true;return}let pos=rayToGround(e.clientX,e.clientY);tapCandidate={id:e.pointerId,x:e.clientX,y:e.clientY,time:performance.now(),world:pos};if(designer.mode==='move'){let b=pos&&pickStructure(pos.x,pos.y);if(b){designer.drag={b,from:{x:b.x,z:b.y}};designer.ghost={x:b.x,z:b.y};}}});
world3d.addEventListener('pointermove',e=>{if(!touchPointers.has(e.pointerId))return;let prev=touchPointers.get(e.pointerId);touchPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(cameraDrag?.pinch&&touchPointers.size===2){let p=[...touchPointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),cx=(p[0].x+p[1].x)/2,cy=(p[0].y+p[1].y)/2;scene3d.yaw=cameraDrag.yaw-(cx-cameraDrag.cx)*.009;scene3d.pitch=clamp(cameraDrag.pitch+(cy-cameraDrag.cy)*.005,.38,1.2);setZoom(cameraDrag.zoom*d/cameraDrag.distance);return}if(cameraDrag&&!cameraDrag.pinch){scene3d.yaw=cameraDrag.yaw-(e.clientX-cameraDrag.x)*.011;scene3d.pitch=clamp(cameraDrag.pitch+(e.clientY-cameraDrag.y)*.007,.32,1.22);return}if(designer.drag){let pos=rayToGround(e.clientX,e.clientY);if(pos)designer.ghost={x:Math.round(pos.x*2)/2,z:Math.round(pos.y*2)/2};return}if(tapCandidate&&Math.hypot(e.clientX-tapCandidate.x,e.clientY-tapCandidate.y)>10)tapCandidate.moved=true});
function releasePointer(e){let pt=touchPointers.get(e.pointerId);touchPointers.delete(e.pointerId);if(cameraDrag){if(!touchPointers.size){cameraDrag=null;tapCandidate=null}else if(touchPointers.size<2){cameraDrag=null;tapCandidate=null}return}if(designer.drag){let b=designer.drag.b,p=rayToGround(e.clientX,e.clientY);if(p&&Math.hypot(p.x-b.x,p.y-b.y)>.4)moveStructure(b,p.x,p.y);else{designer.chosen=b;toast('Tap a second spot to drop this structure, or drag it')};designer.drag=null;designer.ghost=null;tapCandidate=null;return}if(tapCandidate&&!tapCandidate.moved&&tapCandidate.id===e.pointerId&&performance.now()-tapCandidate.time<850){let p=rayToGround(e.clientX,e.clientY);if(designer.mode==='move'&&designer.chosen){let b=designer.chosen;designer.chosen=null;designer.ghost=null;moveStructure(b,p.x,p.y)}else modeTap(p)}tapCandidate=null}
world3d.addEventListener('pointerup',releasePointer);world3d.addEventListener('pointercancel',e=>{touchPointers.delete(e.pointerId);designer.drag=null;designer.ghost=null;cameraDrag=null;tapCandidate=null});world3d.addEventListener('contextmenu',e=>e.preventDefault());world3d.addEventListener('wheel',e=>{e.preventDefault();setZoom(currentZoom+(e.deltaY<0?.1:-.1))},{passive:false});
