const v05Actions=e=>{const b=e.target.closest('[data-v05]');if(!b)return;e.preventDefault();e.stopPropagation();let op=b.dataset.v05;let type=b.dataset.type;if(op==='close'){hideModal();return}if(op==='studio'){showStudio();return}if(op==='camera'){showControlSettings();return}if(op==='newBuild'){if(!canAfford(type)){toast('Gather materials for '+COST[type].name);return}activateDesigner('place',type);return}if(op==='terrain'){activateDesigner('terrain',type);return}if(op==='mode'){activateDesigner(b.dataset.mode);return}if(op==='endEdit'){stopDesigner();return}if(op==='undo'){undoDesign();return}if(op==='rotateObject'){rotateSelected();return}if(op==='chooseStyle'){chooseStyle(b.dataset.group,b.dataset.choice);return}if(op==='doneStyle'){hideModal();stopDesigner();return}if(op==='unlock'){unlockZone(b.dataset.zone);return}if(op==='orbitLeft'){rotateCamera(-1);return}if(op==='orbitRight'){rotateCamera(1);return}};
