// Show genuinely different room divisions when a cottage's floor plan is changed.
const v05OriginalInterior=renderInterior;
renderInterior=function(){v05OriginalInterior();let house=state.built.find(b=>b.type==='cottage'&&uiHomeKey!=='player'&&b.resident===Number(uiHomeKey));let layout=house?.style?.layout||'Cozy single room',canvas=$('interiorOverlay').querySelector('.roomCanvas'),floor=$('interiorOverlay').querySelector('.roomFloor'),tools=$('interiorOverlay').querySelector('.roomTools');if(!canvas||!floor)return;canvas.dataset.layout=layout;floor.style.background=layout==='Garden nook'?'linear-gradient(105deg,#acd4a5 0 32%,transparent 32%),var(--floor)':layout==='Workshop corner'?'linear-gradient(135deg,#c7b0a2 0 33%,transparent 33%),var(--floor)':layout==='Living + sleeping'?'linear-gradient(90deg,#d8d0b6 0 50%,#c6b1a4 50% 51%,transparent 51%),var(--floor)':'';tools?.insertAdjacentHTML('afterbegin',`<p class="sub">🏡 Room plan: <b>${esc(layout)}</b>. Furniture and wallpaper remain editable.</p>`)};
const oldV05ShowStyle=showHouseStyle;
showHouseStyle=function(index){oldV05ShowStyle(index);if(index>=0&&state.built[index]?.resident!==null){$('modalBody')?.querySelector('.actions')?.insertAdjacentHTML('afterbegin','<button class="btn" data-v05="visitHome">🚪 See this room layout</button>')}};
document.addEventListener('click',e=>{let b=e.target.closest('[data-v05="visitHome"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();let house=state.built[activeStyleIndex];if(house?.resident!==null&&house?.resident!==undefined)enterInterior(String(house.resident))},true);
// Old v0.4 standalone world fallback has a right-click-to-walk handler, so handle camera edit modes using dock controls.
const oldV05ShowMenu=showPanel;
showPanel=function(p){oldV05ShowMenu(p);if(p==='menu'){$('modalBody').innerHTML=$('modalBody').innerHTML.replaceAll('FATHERMON TOWNSHIP 0.4','FATHERMON TOWNSHIP 0.5').replaceAll('A Town Comes Alive','Build Your Dream Town');$('modalBody').querySelector('.hubgrid')?.insertAdjacentHTML('afterbegin','<button data-v05="studio">🎨 Design Studio</button>')}};

// Exterior styles are structural choices, not only a recolor.
Object.assign(exteriorOptions,{
 roofShape:[['Classic gable','Classic gable'],['Flat modern','Flat modern'],['Pyramid','Pyramid']],
 doorShape:[['Single','Single'],['Double','Double'],['Round top','Round top']],
 windowShape:[['Square','Square'],['Tall','Tall'],['Shutters','Shutters']]
});
const houseStylesPrior=showHouseStyle;
showHouseStyle=function(i){houseStylesPrior(i);const h=state.built[i];if(!h||h.type!=='cottage')return;let el=$('modalBody'),title=['roofShape','doorShape','windowShape'];const html=title.map(gr=>`<h3>${gr==='roofShape'?'🏗️ Roof shape':gr==='doorShape'?'🚪 Door style':'🪟 Window style'}</h3><div class="styleRow">${exteriorOptions[gr].map(([label,v])=>`<button class="styleChip ${(h.style||{})[gr]===v?'chosen':''}" style="--chip:#b6d9c8" data-v05="chooseStyle" data-group="${gr}" data-choice="${v}">${label}</button>`).join('')}</div>`).join('');const actions=el.querySelector('.actions');if(actions)actions.insertAdjacentHTML('beforebegin',html)};
// Distinct roof geometry, window proportions and door widths are built into the WebGL mesh.
cottage=function(g,b){let s=b.style||{},wall=s.wall||'#f8dbaa',roof=s.roof||'#d67b60',door=s.door||'#6f563d',window=s.window||'#a3e7e4';const roofShape=s.roofShape||'Classic gable',doorShape=s.doorShape||'Single',windowShape=s.windowShape||'Square';g.local(b.x,b.y,(b.rotation||0)*Math.PI/2,()=>{
 g.box(0,0,2.5,2.15,1.8,wall);g.box(0,1.16,doorShape==='Double'?1.19:doorShape==='Round top'?.78:.73,.09,doorShape==='Round top'?1.17:1.43,door,.03);
 if(doorShape==='Double'){g.box(0,1.23,.06,.11,1.41,'#e8c58c',.04);g.box(-.16,1.27,.10,.04,.11,'#e5d0a0',.54);g.box(.16,1.27,.10,.04,.11,'#e5d0a0',.54)}
 if(doorShape==='Round top'){g.disc(0,1.12,.38,door,1.14,12)}
 const width=windowShape==='Tall'?.38:.48,height=windowShape==='Tall'?.85:.48;
 for(let wx of [-.78,.78]){g.box(wx,1.16,width,.12,height,window,windowShape==='Tall'?.62:1.02);g.box(wx,1.21,.06,.08,height,'#fffae6',windowShape==='Tall'?.62:1.02);if(windowShape==='Shutters'){g.box(wx-.33,1.18,.18,.14,.68,'#8ab2a4',.94);g.box(wx+.33,1.18,.18,.14,.68,'#8ab2a4',.94)}}
 if(roofShape==='Flat modern'){g.box(0,0,2.95,2.65,.24,roof,1.80);g.box(0,0,3.1,2.75,.1,'#fdf0d0',1.99);g.box(0,0,2.94,2.66,.13,roof,2.07)}
 else if(roofShape==='Pyramid'){const peak=[0,3.18,0],a=[-1.50,1.78,-1.41],b=[1.50,1.78,-1.41],c=[1.50,1.78,1.41],d=[-1.50,1.78,1.41];g.tri(a,b,peak,roof,.77);g.tri(b,c,peak,roof,.89);g.tri(c,d,peak,roof,1.13);g.tri(d,a,peak,roof,.93)}
 else{g.quad([-1.45,1.74,-1.38],[1.45,1.74,-1.38],[1.45,2.86,0],[-1.45,2.86,0],roof,.82);g.quad([-1.45,2.86,0],[1.45,2.86,0],[1.45,1.74,1.38],[-1.45,1.74,1.38],roof,1.10);g.tri([-1.45,1.74,-1.38],[-1.45,1.74,1.38],[-1.45,2.86,0],wall,.89);g.tri([1.45,1.74,-1.38],[1.45,2.86,0],[1.45,1.74,1.38],wall,.85)}
})};


